import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import LinkButton from 'flarum/common/components/LinkButton';
import SessionDropdown from 'flarum/forum/components/SessionDropdown';
import UserControls from 'flarum/forum/utils/UserControls';
import { setLinks } from '../common/links';
const EXT = 'ernestdefoe-member-desk';

/*
 * forum.js only wires routes and two links for staff; the pages are one lazy chunk.
 */
const lazy = name => () => import(/* webpackChunkName: 'forum/components', webpackMode: 'lazy-once' */ './components').then(chunk => ({
  default: chunk[name]
}));
const canView = () => !!app.forum.attribute('memberDesk')?.view;
app.initializers.add(EXT, () => {
  // /member-desk/log before /member-desk/:id: routes match in order.
  app.routes['member-desk.index'] = {
    path: '/member-desk',
    component: lazy('ForumListPage')
  };
  app.routes['member-desk.log'] = {
    path: '/member-desk/log',
    component: lazy('ForumLogPage')
  };
  app.routes['member-desk.member'] = {
    path: '/member-desk/:id',
    component: lazy('ForumMemberPage')
  };
  const base = () => app.forum.attribute('baseUrl');
  setLinks({
    list: () => app.route('member-desk.index'),
    member: id => app.route('member-desk.member', {
      id
    }),
    log: () => app.route('member-desk.log'),
    profile: username => app.route('user', {
      username
    }),
    discussion: (id, slug, near) => `${base()}/d/${id}${slug ? '-' + slug : ''}${near ? '/' + near : ''}`,
    admin: false
  });
  extend(SessionDropdown.prototype, 'items', function (items) {
    if (!canView()) return;
    items.add('memberDesk', m(LinkButton, {
      icon: "fas fa-address-book",
      href: app.route('member-desk.index')
    }, app.translator.trans(`${EXT}.forum.nav`)), 55);
  });
  extend(UserControls, 'moderationControls', function (items, user) {
    if (!canView()) return;
    items.add('memberDesk', m(LinkButton, {
      icon: "fas fa-address-card",
      href: app.route('member-desk.member', {
        id: user.id()
      })
    }, app.translator.trans(`${EXT}.forum.open_member`)), -50);
  });
});